import sys
from pathlib import Path
src = Path('source')
if not src.is_dir():
    src = Path(__file__).resolve().parent / 'source'
sys.path.insert(0, str(src))
from automol import graph

def sig(gra):
    syms = graph.atom_symbols(gra)
    out = []
    for coord in graph.rotational_coordinates(gra):
        seq = tuple(syms[k] for k in coord)
        out.append(min(seq, seq[::-1]))
    return sorted(out)

def shift_ts(n):
    atm = {i: 'C' for i in range(n)}
    hyd = {i: (3 if i in (0, n - 1) else 2) for i in range(n)}
    bonds = [(i, i + 1) for i in range(n - 1)]
    gra = graph.from_data(atm, bonds, atm_imp_hyd_dct=hyd)
    return graph.ts_graph(gra, frm_bnd_keys=[(0, 2)], brk_bnd_keys=[(0, 1)])

s5 = sig(shift_ts(5))
assert len(s5) > 0, 'expected a nonempty rotor observation for the longer chain'
s4 = sig(shift_ts(4))
assert s4 != s5, 'changed connectivity collapsed to the same rotor observation'
